var n=`1416-saksak`;var s=`world-1416`;var i=`PG`;var t=`oceania`;var o=6;var r=85;var l={en:`Saksak`,ua:`Саксак`};var g={en:`Saksak is a Papua New Guinean banana-and-sago parcel with coconut. This recipe uses catalog sago pearls and food-safe banana leaves.`,ua:`Саксак, папуаські пакунки із сагових перлин і банана з кокосом. Рецепт використовує сагові перлини з каталогу та харчове бананове листя.`};var m=[{en:`Rinse small sago pearls, soak in warm water for 20 minutes and drain. The pearls must finish cooking completely in the steamer.`,ua:`Промийте дрібні сагові перлини, замочіть у теплій воді на 20 хвилин і відцідіть. Вони мають повністю приготуватися на парі.`,t:[`soaking-dried-produce`,`draining`],m:20,i:[[`sago-pearls`,260,`g`],[`water`,650,`ml`]]},{en:`Mash ripe bananas and stir with softened sago, sugar and salt.`,ua:`Розімніть стиглі банани та змішайте з розм’якшеним саго, цукром і сіллю.`,t:[`mashing`,`mixing`],m:8,i:[[`banana`,430,`g`],[`caster-sugar`,40,`g`],[`sea-salt`,2,`g`]]},{en:`Briefly soften food-grade banana leaves over steam. Wrap the mixture into six tightly sealed parcels.`,ua:`Коротко розм’якшіть харчове бананове листя парою. Загорніть суміш у шість щільних пакунків.`,t:[`leaf-wrapping`],m:12,i:[[`banana-leaf`,6,`leaf`]]},{en:`Steam over steadily boiling water for 35–45 minutes until sago pearls become uniformly translucent with no chalky core.`,ua:`Готуйте на парі над водою, що постійно кипить, 35–45 хвилин, доки всі перлини саго не стануть прозорими без білого сирого осердя.`,t:[`banana-leaf-steaming`],m:40,i:[]},{en:`Warm coconut milk gently. Open one parcel to check doneness, then serve dumplings with the coconut milk spooned over.`,ua:`Обережно підігрійте кокосове молоко. Розгорніть один пакунок, щоб перевірити готовність, і подавайте кльоцки, поливши кокосовим молоком.`,t:[`gentle-simmering`],m:5,i:[[`coconut-milk`,350,`ml`]]}];var u={slug:n,id:s,country:`PG`,region:t,servings:6,minutes:85,title:l,text:g,steps:m};export{i as country,u as default,s as id,r as minutes,t as region,o as servings,n as slug,m as steps,g as text,l as title};